//! Known answers for JSON → CDE and the derived digests (CC 2.7.11).
//!
//! `tests/vectors/cde/cde_json_v1.json` was generated by `gen_cde_json.py`
//! beside it, with its own CBOR encoder and Python's `Decimal`, sharing no
//! code with verify. CDE has no floats: an integral number is an integer, a
//! non-integral one the normalised tag-4 decimal of its exact text, and
//! anything outside CBOR's integer range is refused.

use ciris_verify_core::cde::{
    self, ceg_digest, digest_value, from_json, CdeError, JsonError, Value,
};
use serde_json::Value as J;

const FILE: &str = include_str!("vectors/cde/cde_json_v1.json");

fn file() -> J {
    serde_json::from_str(FILE).unwrap()
}

fn s<'a>(c: &'a J, k: &str) -> &'a str {
    c[k].as_str().unwrap()
}

fn d32(h: &str) -> [u8; 32] {
    hex::decode(h).unwrap().try_into().unwrap()
}

#[test]
fn json_maps_to_cde() {
    let f = file();
    let cases = f["json"].as_array().unwrap();
    assert!(cases.len() >= 28);
    for c in cases {
        let got = from_json(s(c, "json"));
        match c.get("cde_hex") {
            Some(h) => {
                let v = got.unwrap_or_else(|e| panic!("{}: {e}", s(c, "what")));
                let bytes = cde::encode(&v);
                assert_eq!(hex::encode(&bytes), h.as_str().unwrap(), "{}", s(c, "what"));
                // Every encoding is CDE and reads back as itself.
                assert_eq!(cde::decode(&bytes).unwrap(), v, "{}", s(c, "what"));
            },
            None => assert_eq!(
                got,
                Err(JsonError::NumberUnrepresentable),
                "{}",
                s(c, "what")
            ),
        }
    }
}

#[test]
fn not_json_is_refused() {
    let f = file();
    for c in f["json_refusals"].as_array().unwrap() {
        let got = from_json(s(c, "json"));
        assert!(
            matches!(got, Err(JsonError::Syntax { .. } | JsonError::DuplicateKey)),
            "{}: {got:?}",
            s(c, "what")
        );
    }
    assert_eq!(
        from_json(r#"{"a": 1, "a": 2}"#),
        Err(JsonError::DuplicateKey)
    );
}

#[test]
fn a_decimal_fraction_decodes_only_normalised() {
    let f = file();
    for c in f["decode_refusals"].as_array().unwrap() {
        let b = hex::decode(s(c, "cde_hex")).unwrap();
        assert_eq!(
            cde::decode(&b),
            Err(CdeError::DecimalNotNormal),
            "{}",
            s(c, "what")
        );
    }
}

#[test]
fn derived_digests() {
    let f = file();
    for c in f["call"].as_array().unwrap() {
        let args = from_json(s(c, "arguments_json"));
        let Some(want) = c.get("digest") else {
            assert_eq!(
                args,
                Err(JsonError::NumberUnrepresentable),
                "{}",
                s(c, "what")
            );
            continue;
        };
        let m = [
            Value::Text(s(c, "verb").into()),
            Value::Text(s(c, "tool").into()),
            args.unwrap(),
            Value::Text(s(c, "channel").into()),
        ];
        let mut a = vec![Value::Text("CEG-call/2".into())];
        a.extend_from_slice(&m);
        assert_eq!(
            hex::encode(cde::encode(&Value::Array(a))),
            s(c, "cde_hex"),
            "{}",
            s(c, "what")
        );
        assert_eq!(
            hex::encode(ceg_digest("CEG-call/2", &m)),
            want.as_str().unwrap(),
            "{}",
            s(c, "what")
        );
    }
    for c in f["review"].as_array().unwrap() {
        let rec = cde::decode(&hex::decode(s(c, "record_cde_hex")).unwrap()).unwrap();
        assert_eq!(
            hex::encode(ceg_digest("CEG-review/2", &[rec])),
            s(c, "digest"),
            "{}",
            s(c, "what")
        );
    }
    for c in f["profile"].as_array().unwrap() {
        let m: Vec<Value> = c["links"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| digest_value(&d32(l.as_str().unwrap())))
            .collect();
        let mut a = vec![Value::Text("CEG-profile/2".into())];
        a.extend_from_slice(&m);
        assert_eq!(
            hex::encode(cde::encode(&Value::Array(a))),
            s(c, "cde_hex"),
            "{}",
            s(c, "what")
        );
        assert_eq!(
            hex::encode(ceg_digest("CEG-profile/2", &m)),
            s(c, "digest"),
            "{}",
            s(c, "what")
        );
    }
}

/// CIRISConstitution's own known answers for the three derived digests (CC
/// 2.7.11, `formal/admission/digest_vectors.json` at v1.0-rc21-wire e6fd7c6),
/// vendored at `tests/vectors/cc/ceg_digest_vectors.json` and pinned by
/// SHA-256: 18 calls (four refused `call_argument_unrepresentable`), three
/// reviews and three profiles.
#[test]
fn the_constitutions_digest_vectors() {
    const CC: &str = include_str!("vectors/cc/ceg_digest_vectors.json");
    assert_eq!(
        hex::encode(<sha2::Sha256 as sha2::Digest>::digest(
            CC.replace("\r\n", "\n").as_bytes()
        )),
        "10367ac8fccfe800bd6c5c4d6593461763e22ca6229f0c5c6d637ce689416235"
    );
    let f: J = serde_json::from_str(CC).unwrap();
    let digest = |c: &J| c["digest"][1].as_str().unwrap().to_owned();
    let calls = f["call"].as_array().unwrap();
    assert_eq!(calls.len(), 18);
    for c in calls {
        let args = from_json(s(c, "arguments_json"));
        if c.get("refused").is_some() {
            assert_eq!(
                args,
                Err(JsonError::NumberUnrepresentable),
                "{}",
                s(c, "what")
            );
            continue;
        }
        let m = [
            Value::Text(s(c, "verb").into()),
            Value::Text(s(c, "tool").into()),
            args.unwrap_or_else(|e| panic!("{}: {e}", s(c, "what"))),
            Value::Text(s(c, "channel").into()),
        ];
        let mut a = vec![Value::Text("CEG-call/2".into())];
        a.extend_from_slice(&m);
        assert_eq!(
            hex::encode(cde::encode(&Value::Array(a))),
            s(c, "cde_hex"),
            "{}",
            s(c, "what")
        );
        assert_eq!(
            hex::encode(ceg_digest("CEG-call/2", &m)),
            digest(c),
            "{}",
            s(c, "what")
        );
    }
    for c in f["review"].as_array().unwrap() {
        let rec = cde::decode(&hex::decode(s(c, "record_cde_hex")).unwrap()).unwrap();
        assert_eq!(
            hex::encode(ceg_digest("CEG-review/2", &[rec])),
            digest(c),
            "{}",
            s(c, "what")
        );
    }
    for c in f["profile"].as_array().unwrap() {
        let m: Vec<Value> = c["links"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| digest_value(&d32(l[1].as_str().unwrap())))
            .collect();
        assert_eq!(
            hex::encode(ceg_digest("CEG-profile/2", &m)),
            digest(c),
            "{}",
            s(c, "what")
        );
    }
}
